#pragma once
#include "kstationProgramVoicesTask.h"
#include "kstationNativeVoiceAllocation.h"
#include "kstationNativeVoiceUpdate.h"
#include "kstationNativeDspTransfer.h"
#include "kstationNativeMidiPump.h"
#include <variant>
namespace kstation {
class NativeProgramVoices final {
 using T=ProgramVoicesTask;using I=ProgramVoiceInitTask;using S=ProgramVoiceStatusTask;using K=ProgramHeldKeysClearTask;
 struct Job{std::variant<T,I,S,K>task{T{0}};unsigned child=0;};
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,4>CodeRanges{{{0x2baa,0x2bc8},{0x763e,0x76d6},{0x816c,0x8190},{0x837c,0x8394}}};
 bool active()const{return depth_||allocation_.active()||update_.active()||dsp_.active();}void reset(){depth_=0;allocation_.reset();update_.reset();dsp_.reset();steps_=0;}uint64_t steps()const{return steps_;}
 static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(NativeVoiceAllocation::candidate(at)){if(!allocation_.step(c))return false;++steps_;return true;}if(NativeVoiceUpdate::candidate(at)){if(!update_.step(c))return false;++steps_;return true;}if(NativeDspTransfer::candidate(at)){if(!dsp_.step(c))return false;++steps_;return true;}
  if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x763e||at==0x7644)j.task.emplace<T>(uint8_t(c.reg8(14)),at==0x763e);else if(at==0x816c)j.task.emplace<I>();else if(at==0x837c)j.task.emplace<S>();else if(at==0x2baa)j.task.emplace<K>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K program voice capacity");jobs_[depth_++]=j;}
  auto&j=jobs_[depth_-1];resume(j,c);if(at!=boundary(j))throw std::logic_error("Native K program voice boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
  std::visit([&](auto&t){using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,T>)t.advanceBefore(cost,cr,[&](T::Read f){return readVoices(t,c,f);},[&](T::Write f,unsigned value){if(f==T::Write::Age){c.write32(int32_t(value),int(t.voice()+8));val(c,c.reg32(2));}else{val(c,c.reg8(f==T::Write::Part?14:8));c.write8(int8_t(value),f==T::Write::Part?0xd028:0xd023);}});else if constexpr(std::is_same_v<J,I>)t.advanceBefore(cost,cr,[&]{c.reg8(14)=c.read8(int(t.part()+15));val(c,c.reg8(14));return uint8_t(c.reg8(14));},[&](bool generation,unsigned value){c.write8(int8_t(value),int(t.part()+(generation?15:14)));val(c,c.reg8(14));});else if constexpr(std::is_same_v<J,S>)t.advanceBefore(cost,cr,[&]{c.reg8(1)=c.read8(0xd023);val(c,c.reg8(1));return uint8_t(c.reg8(1));},[&](unsigned value){val(c,c.reg8(1));c.write8(int8_t(value),0xd0f0);});else t.advanceBefore(cost,cr,[&](unsigned index,unsigned value){--c.reg32(1);c.write8(int8_t(value),int(0xcbed-index));val(c,c.reg8(0));c.clockI(2);});},j.task);
  if(c.cycles-begin!=cost)throw std::logic_error("Native K program voice clocks differ");auto done=std::visit([](const auto&t){return t.complete();},j.task);if(done)--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;
 }
private:
 static void val(Stage1Cpu&c,int value){midi_projection::val(c,value);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}
 static void dec(Stage1Cpu&c,unsigned r){int old=c.reg8(r),v=old-1;val(c,v);if((old&~v)&128)c.ccr|=2;c.reg8(r)=int8_t(v);}static void increment(Stage1Cpu&c,unsigned r){int old=c.reg8(r),v=old+1;val(c,v);if((~old&v)&128)c.ccr|=2;c.reg8(r)=int8_t(v);}
 static void call(Job&j,Stage1Cpu&c,unsigned target,unsigned returned){j.child=target;midi_projection::call(c,target,returned,true);}
 static bool waiting(const Job&j){return std::visit([](const auto&t){using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,K>)return false;else return t.awaiting();},j.task);}
 static void resume(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<T>(&j.task)){if(t->awaiting())t->resumeChild(t->child()==T::Child::Voice?uint32_t(c.reg32(3)):0);}else if(auto*t=std::get_if<I>(&j.task)){if(t->awaiting())t->resumeChild(uint32_t(c.reg32(0)));}else if(auto*t=std::get_if<S>(&j.task)){if(t->awaiting())t->resume();}}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,T>){static constexpr unsigned a[]={0x763e,0x7642,0x7644,0x7646,0x764c,0x7652,0x7654,0x765a,0x7660,0x7662,0x7664,0x7666,0x766a,0x7672,0x7674,0x767c,0x767e,0x7680,0x7682,0x7684,0x7686,0x768a,0x7694,0x769e,0x76a2,0x76a4,0x76a6,0x76a8,0x76ac,0x76b0,0x76b4,0x76b8,0x76be,0x76c0,0x76c6,0x76c8,0x76ca,0x76cc,0x76ce,0x76d0,0x76d4,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<J,I>){static constexpr unsigned a[]={0x816c,0x816e,0x8172,0x8174,0x817c,0x8184,0x8186,0x818e,0};return a[unsigned(t.stage())];}else if constexpr(std::is_same_v<J,S>){static constexpr unsigned a[]={0x837c,0x8380,0x8386,0x838c,0x838e,0x8392,0};return a[unsigned(t.stage())];}else{static constexpr unsigned a[]={0x2baa,0x2bac,0x2bb0,0x2bb6,0x2bba,0x2bbc,0x2bbe,0x2bc0,0x2bc4,0x2bc6,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){switch(boundary(j)){case 0x768a:case 0x7694:return 10;case 0x766a:case 0x7674:case 0x8174:case 0x817c:case 0x8186:return 8;case 0x7646:case 0x764c:case 0x7654:case 0x765a:case 0x76b8:case 0x76c0:case 0x8380:case 0x8386:case 0x2bb0:return 6;case 0x763e:case 0x7666:case 0x7686:case 0x769e:case 0x76a8:case 0x76ac:case 0x76b0:case 0x76b4:case 0x76d0:case 0x816e:case 0x837c:case 0x838e:case 0x2bac:case 0x2bb6:case 0x2bc0:return 4;default:return 2;}}
 static unsigned bus(uint32_t a,unsigned n,int previous){return voice_update_projection::bus(a,n,previous);}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);auto read=[&](unsigned a,unsigned n){cr.read=bus(a,n,last);};auto write=[&](unsigned a,unsigned n){cr.write=bus(a,n,c.writeHistory());};if(auto*t=std::get_if<T>(&j.task)){using Q=T::Stage;switch(t->stage()){case Q::PublishPart:write(0xd028,1);break;case Q::PublishIndex:case Q::WriteIndex:write(0xd023,1);break;case Q::ReadPart:read(0xd028,1);break;case Q::ReadCount:read(0xd022,1);break;case Q::ReadAge:read(t->voice()+8,2);break;case Q::ReadOwner:read(t->voice()+4,1);break;case Q::PublishAge:write(t->voice()+8,4);break;case Q::ReadPatch:read(t->voice(),4);break;case Q::ReadIndex:read(0xd023,1);break;default:break;}}else if(auto*t=std::get_if<I>(&j.task)){if(t->stage()==I::Stage::ReadGeneration)read(t->part()+15,1);else if(t->stage()==I::Stage::PublishEnable||t->stage()==I::Stage::PublishGeneration)write(t->part()+(t->stage()==I::Stage::PublishEnable?14:15),1);}else if(auto*t=std::get_if<S>(&j.task)){if(t->stage()==S::Stage::Read)read(0xd023,1);else if(t->stage()==S::Stage::Publish)write(0xd0f0,1);}else if(auto*t=std::get_if<K>(&j.task)){if(t->stage()==K::Stage::Publish)write(0xcbed-t->index(),1);}return cr;}
 static unsigned readVoices(const T&t,Stage1Cpu&c,T::Read field){switch(field){case T::Read::Part:c.reg8(9)=c.read8(0xd028);val(c,c.reg8(9));return uint8_t(c.reg8(9));case T::Read::Count:c.reg8(8)=c.read8(0xd022);val(c,c.reg8(8));return uint8_t(c.reg8(8));case T::Read::Age:c.reg16(2)=int16_t(c.read16(t.voice()+8));val(c,c.reg16(2));return uint16_t(c.reg16(2));case T::Read::Owner:c.reg8(8)=c.read8(t.voice()+4);val(c,c.reg8(8));return uint8_t(c.reg8(8));case T::Read::Patch:c.reg32(6)=int32_t(c.read32(t.voice()));val(c,c.reg32(6));return uint32_t(c.reg32(6));case T::Read::Index:c.reg8(8)=c.read8(0xd023);val(c,c.reg8(8));return uint8_t(c.reg8(8));}return 0;}
 static void project(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<T>(&j.task)){using Q=T::Stage;switch(t->stage()){case Q::PrepareRelease:c.reg16(2)=1;val(c,1);break;case Q::PrepareClear:c.reg16(2)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::ClearIndex:c.reg8(8)=0;val(c,0);break;case Q::RetainCount:push(c,0,true);break;case Q::RetainPart:push(c,1,true);break;case Q::RetainMode:push(c,2,true);break;case Q::SelectVoice:call(j,c,0x72ba,0x766a);break;case Q::CompareOwner:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(9)),uint8_t(c.reg8(8)),8,true);break;case Q::MaskAge:c.reg8(2)&=0x3f;val(c,c.reg8(2));break;case Q::MarkAge:c.reg8(10)|=1;val(c,c.reg8(10));break;case Q::RetainAge:c.reg16(10)=c.reg16(2);val(c,c.reg16(10));break;case Q::PrepareTail:c.reg16(2)=-1;val(c,-1);break;case Q::SelectDsp:call(j,c,0x5bb8,0x76a2);break;case Q::ReadMode:pop(c,0,true);break;case Q::RetainModeValue:push(c,0,true);break;case Q::PrepareGain:c.reg16(9)=0x1000;val(c,c.reg16(9));break;case Q::PrepareCommand:c.reg16(4)=0x55;val(c,0x55);break;case Q::WriteGain:call(j,c,0x5bec,0x76b4);break;case Q::WriteGate:call(j,c,0x6f44,0x76b8);break;case Q::AdvanceIndex:increment(c,8);break;case Q::RestoreMode:pop(c,2,true);break;case Q::RestorePart:pop(c,1,true);break;case Q::RestoreCount:pop(c,0,true);break;case Q::DecrementCount:dec(c,8);break;case Q::ClearKeys:call(j,c,0x2baa,0x76d4);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<I>(&j.task)){using Q=I::Stage;switch(t->stage()){case Q::CopyPart:c.reg8(8)=c.reg8(14);val(c,c.reg8(8));break;case Q::Address:call(j,c,0x72d4,0x8172);break;case Q::PrepareEnable:c.reg8(14)=1;val(c,1);break;case Q::AdvanceGeneration:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),8,8,false));break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<S>(&j.task)){using Q=S::Stage;switch(t->stage()){case Q::Address:c.reg16(4)=int16_t(0x802d);val(c,c.reg16(4));break;case Q::ClearFraction:c.reg16(9)=0;c.ccr=uint8_t((c.ccr&~0x2f)|4);break;case Q::Send:call(j,c,0x165e,0x8392);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
  else if(auto*t=std::get_if<K>(&j.task)){using Q=K::Stage;switch(t->stage()){case Q::RetainValue:push(c,0,true);break;case Q::RetainPointer:push(c,1,false);break;case Q::Bind:c.reg32(1)=0xcbee;val(c,c.reg32(1));break;case Q::Count:c.reg16(0)=16;val(c,16);break;case Q::Decrement:dec(c,8);break;case Q::RestorePointer:pop(c,1,false);break;case Q::RestoreValue:pop(c,0,true);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
 }
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeVoiceAllocation allocation_;NativeVoiceUpdate update_;NativeDspTransfer dsp_;
};
}
